const fs = require('fs');

const [a, b] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(BigInt);

let count = 0;

for (let length = 2; length <= 60; length++) {
    const allOnes = (1n << BigInt(length)) - 1n;

    for (let zeroPosition = 0; zeroPosition < length - 1; zeroPosition++) {
        const value = allOnes - (1n << BigInt(zeroPosition));
        if (value >= a && value <= b) count++;
    }
}

console.log(count.toString());

